package com.wheelwright.evidence.v2.portfolio;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioJson.*;
import static com.wheelwright.evidence.v2.portfolio.PortfolioRepository.*;

/** Admitted synthetic source-predicate specimens. Does not establish that broker feeds prove association. */
class PortfolioOrderEvaluationTest {
 final JsonNode bundle;final Instant now=Instant.parse("2026-10-20T18:00:00Z");
 PortfolioOrderEvaluationTest()throws Exception{bundle=JSON.readTree(Files.readString(Path.of("../docs/reviews/api-v2-foundational-contract-2026-10-20/examples/resources.json")));}
 ObjectNode construction(){return (ObjectNode)bundle.path("resources").path(bundle.at("/names/bwb").asText()).path("value").deepCopy();}
 ObjectNode position(ObjectNode c){var p=obj();p.set("self",c.path("position"));p.set("account",c.path("account"));p.set("evaluation",PortfolioMath.evaluate(c,Map.of(),now));return p;}
 Document order(ObjectNode c,boolean opening){String uri="/v2/orders/"+UUID.randomUUID();String account=c.at("/account/href").asText().substring("/v2/accounts/".length());var source=source(account,UUID.randomUUID().toString(),"/synthetic/verifiedActivity",null,"2026-10-20T17:00:00Z","SYNTHETIC");source.put("requiredCapability","account.orders.read:"+account);var evidence=array().add(source);var o=obj().put("status",opening?"FILLED":"WORKING").put("orderType","LIMIT").put("priceEffect","DEBIT");o.set("self",link(uri));o.set("account",c.path("account"));o.set("evidence",evidence);var association=obj().put("status","ESTABLISHED").put("targetKind","CONSTRUCTION");association.set("target",c.path("self"));association.set("evidence",evidence);association.set("authority",PortfolioSources.authority(account,UUID.randomUUID().toString(),"RECONCILED_DOCUMENTED_ACTIVITY","ESTABLISHED",evidence,List.of(uri,c.at("/self/href").asText()),"Synthetic already-admitted source predicate; not a live brokerage assertion."));association.set("nodeIds",array());o.set("associations",array().add(association));
  var legs=array();int index=0;for(var leaf:leaves(c.path("composition"))){boolean buy=leaf.path("side").asText().equals("LONG");var leg=obj().put("action",opening?(buy?"BUY_TO_OPEN":"SELL_TO_OPEN"):(buy?"SELL_TO_CLOSE":"BUY_TO_CLOSE")).put("requestedQuantity",leaf.path("quantity").asText()).put("fillsCoverage","COMPLETE_REPORTED");leg.set("instrument",leaf.path("instrument"));var fills=array();if(opening){String time=index++==0?"2026-10-05T14:00:00Z":"2026-10-05T14:00:01Z";var fill=obj().put("quantity",leaf.path("quantity").asText()).put("price",buy?"2":"1").put("multiplier","100").put("priceUnit","PER_UNDERLYING_UNIT").put("currency","USD").put("executedAt",time);fill.set("evidence",evidence);fill.set("fees",metric(new BigDecimal("1"),"MONEY","USD",time,"REPORTED_TEST_FEE","QUALIFIED",evidence,"ORDER_EVIDENCE"));fills.add(fill);}leg.set("fills",fills);leg.set("filledQuantity",metric(opening?number(leaf.path("quantity")):BigDecimal.ZERO,"CONTRACT",null,"2026-10-20T17:00:00Z","REPORTED","QUALIFIED",evidence,"ORDER_EVIDENCE"));legs.add(leg);}o.set("legs",legs);o.set("limitPrice",metric(new BigDecimal("0.5"),"PRICE","USD","2026-10-20T17:00:00Z","INSTRUCTION","QUALIFIED",evidence,"ORDER_EVIDENCE"));o.set("stopTrigger",na("PRICE",null));o.set("priceConvention",obj().put("unit","PER_UNDERLYING_UNIT").put("multiplier","100").put("packageQuantity","1"));return new Document(Kind.ORDER,uri,account,o,null,null);
 }
 @Test void debitOpeningUsesActualFillsNotInstructionAndFinalFillTime(){var c=construction();var p=position(c);var o=order(c,true);PortfolioOrderEvaluation.apply(p,c,List.of(o),now);assertThat(p.at("/evaluation/timeline/openedAt").asText()).isEqualTo("2026-10-05T14:00:01Z");assertThat(p.at("/evaluation/timeline/originalDays/asOf").asText()).isEqualTo("2026-10-05T14:00:01Z");assertThat(p.at("/evaluation/timeline/originalDays/dependencies").toString()).contains("ORDER_EVIDENCE");BigDecimal cash=BigDecimal.ZERO;for(var leg:o.value().path("legs"))for(var fill:leg.path("fills"))cash=cash.add(number(fill.path("quantity")).multiply(number(fill.path("price"))).multiply(number(fill.path("multiplier"))).multiply(leg.path("action").asText().startsWith("BUY")?BigDecimal.ONE.negate():BigDecimal.ONE));assertThat(number(p.at("/evaluation/openingCashFlow/value"))).isEqualByComparingTo(cash);assertThat(cash).isNegative();assertThat(p.at("/evaluation/payoff/geometry").isObject()).isTrue();}
 @Test void identicalLegsAndTypedPointerNeverCreateAnAssociation(){for(String defect:List.of("absent","subjects","scope","basis","ambiguous")){var c=construction();var p=position(c);var o=order(c,true);var a=(ObjectNode)o.value().path("associations").get(0);switch(defect){case "absent"->o.value().set("associations",array());case "subjects"->((ObjectNode)a.path("authority")).set("subjects",array());case "scope"->((ObjectNode)a.path("authority")).set("account",link("/v2/accounts/foreign"));case "basis"->((ObjectNode)a.path("authority")).put("basis","BROKER_HOLDING_OBSERVATION");default->a.put("status","AMBIGUOUS");}PortfolioOrderEvaluation.apply(p,c,List.of(o),now);assertThat(p.at("/evaluation/timeline/openedAt").isNull()).as(defect).isTrue();}}
 @Test void futureIncompleteOrAmbiguousOpeningNeverCreatesATimeline(){for(String defect:List.of("future","quantity","fills","ambiguous")){var c=construction();var p=position(c);var o=order(c,true);var leg=(ObjectNode)o.value().path("legs").get(0);switch(defect){case "future"->((ObjectNode)leg.path("fills").get(0)).put("executedAt","2026-10-21T12:00:00Z");case "quantity"->leg.put("requestedQuantity","1000");case "fills"->leg.put("fillsCoverage","UNKNOWN");default->{}}PortfolioOrderEvaluation.apply(p,c,defect.equals("ambiguous")?List.of(o,order(c,true)):List.of(o),now);assertThat(p.at("/evaluation/timeline/openedAt").isNull()).as(defect).isTrue();}}
 @Test void workingInstructionDoesNotBecomeFillOrOpeningAndStopNeverBecomesExecution(){var c=construction();var p=position(c);var close=order(c,false);PortfolioOrderEvaluation.apply(p,c,List.of(close),now);assertThat(p.at("/evaluation/timeline/openedAt").isNull()).isTrue();assertThat(p.at("/evaluation/management/orders")).hasSize(1);assertThat(p.at("/evaluation/management/protectiveOrderEvidence").asText()).isEqualTo("UNKNOWN");assertThat(close.value().path("legs")).allSatisfy(l->assertThat(l.path("fills")).isEmpty());var stop=order(c,false);stop.value().put("orderType","STOP_LIMIT");stop.value().set("stopTrigger",stop.value().path("limitPrice"));PortfolioOrderEvaluation.apply(p,c,List.of(stop),now);assertThat(p.at("/evaluation/management/protectiveOrderEvidence").asText()).isEqualTo("PRESENT");assertThat(p.at("/evaluation/management/stopInterpretation").asText()).isEqualTo("PROVISIONAL_NOT_EXECUTION_GUARANTEE");}
}
